package org.codex.nfsugpreview;
import android.app.*;import android.os.*;import android.opengl.*;import java.io.*;import java.nio.*;import java.nio.file.*;import org.json.*;
public final class SkyGpuInstrumentation extends SceneGpuInstrumentation {
 long checks,covered,transparent;
 String verify(NativeSkyPlanes text,int width,int height,int active)throws Exception{
 ByteBuffer lo=text.lower(),hi=text.upper();float weight=(float)text.weight;
 int[] id={0};GLES20.glGenTextures(1,id,0);int tex=id[0];GLES20.glBindTexture(GLES20.GL_TEXTURE_2D,tex);GLES20.glTexImage2D(GLES20.GL_TEXTURE_2D,0,GLES20.GL_RGBA,width,height,0,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,null);GLES20.glGenFramebuffers(1,id,0);int fbo=id[0];GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,fbo);GLES20.glFramebufferTexture2D(GLES20.GL_FRAMEBUFFER,GLES20.GL_COLOR_ATTACHMENT0,GLES20.GL_TEXTURE_2D,tex,0);ok(GLES20.glCheckFramebufferStatus(GLES20.GL_FRAMEBUFFER)==GLES20.GL_FRAMEBUFFER_COMPLETE,"text framebuffer");GLES20.glDisable(GLES20.GL_SCISSOR_TEST);GLES20.glColorMask(true,true,true,true);GLES20.glClearColor(17/255f,34/255f,51/255f,1);GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT);
 try(NativeSkyGpu gpu=new NativeSkyGpu()){gpu.draw(text,active,height);}ByteBuffer actual=ByteBuffer.allocateDirect(width*height*4);GLES20.glReadPixels(0,0,width,height,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,actual);ok(GLES20.glGetError()==0,"text readback");
 for(int y=0;y<height;y++)for(int x=0;x<width;x++){int sy=Math.min(159,(int)(((height-y-.5)*160)/height)),sx=Math.min(239,(int)(((x+.5)*240)/active)),source=(sy*240+sx)*4,at=(y*width+x)*4;boolean glyph=x<active&&(lo.get(source+3)&255)>0;for(int c=0;c<4;c++){int want=glyph?(c==3?255:(int)Math.floor((lo.get(source+c)&255)*(1f-weight)+(hi.get(source+c)&255)*weight+.5f)):(c==3?255:(c+1)*17);if((actual.get(at+c)&255)!=want)throw new AssertionError("text pixel "+x+","+y+" channel "+c);}checks++;if(glyph)covered++;else transparent++;}
 String hash=digest(actual);GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,0);GLES20.glDeleteFramebuffers(1,new int[]{fbo},0);GLES20.glDeleteTextures(1,new int[]{tex},0);return hash;
 }
 @Override public void onStart(){Bundle result=new Bundle();boolean live=false;try{File dir=new File(getTargetContext().getFilesDir(),"sky-fixtures");SkyTest.main(new String[]{dir.getPath()});SkyPlanesTest.main(new String[]{dir.getPath()});byte[] asset=Files.readAllBytes(new File(dir,"asset.bin").toPath()),palette=Files.readAllBytes(new File(dir,"sky-palettes.bin").toPath());startGl();live=true;int count=0,large=0,fractional=0;NativeSkyPlanes last=null;String lastHash=null;for(String line:Files.readAllLines(new File(dir,"samples.tsv").toPath())){String[] x=line.split("\t");int pair=Integer.parseInt(x[0]),mode=Integer.parseInt(x[1]);NativeSky a=new NativeSky(Files.readAllBytes(new File(dir,"pair-"+pair+"-old.bin").toPath())),b=new NativeSky(Files.readAllBytes(new File(dir,"pair-"+pair+"-new.bin").toPath()));last=new NativeSkyPlanes(a.sample(b,asset,Double.parseDouble(x[2]),mode),palette);if(last.weight>0&&last.weight<1)fractional++;lastHash=verify(last,240,160,240);if(count==0||count==16||count==32||count==64||count==164){verify(last,3840,2160,3240);large++;}count++;}endGl();live=false;startGl();live=true;ok(verify(last,240,160,240).equals(lastHash),"sky context recreation");ok(count==330&&large==5&&fractional>0&&covered>0&&transparent>0,"sky branch coverage");JSONObject report=new JSONObject();report.put("result","PASS_ANDROID_SKY_GPU");report.put("samples",count);report.put("fractional_samples",fractional);report.put("four_k_samples",large);report.put("pixel_checks",checks);report.put("covered_samples",covered);report.put("transparent_samples",transparent);report.put("context_recreated",true);report.put("renderer",renderer);report.put("synthetic_palette",true);report.put("game_steps",0);try(FileOutputStream out=getTargetContext().openFileOutput("sky-gpu-report.json",0)){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("stream",report.toString());finish(Activity.RESULT_OK,result);}catch(Throwable e){android.util.Log.e("NFSUGSkyGPU","Failed",e);result.putString("stream","FAIL: "+e);finish(Activity.RESULT_CANCELED,result);}finally{if(live)endGl();}}
}
